export function createOptimisticStore(initialState) {
  let base = initialState;
  let visible = initialState;
  let pending = new Map();
  const subscriptions = new Set();

  function notify() {
    // Snapshot subscriptions so unsubscription cannot disrupt iteration.
    for (const { listener } of Array.from(subscriptions)) {
      try {
        listener();
      } catch {
        // Listener failures must not prevent other notifications.
      }
    }
  }

  function settle(id, shouldConfirm) {
    if (!pending.has(id)) {
      return false;
    }

    const update = pending.get(id);
    const nextPending = new Map(pending);
    nextPending.delete(id);

    // Compute everything before committing any changes.
    const nextBase = shouldConfirm ? update(base) : base;
    let nextVisible = nextBase;

    for (const remainingUpdate of nextPending.values()) {
      nextVisible = remainingUpdate(nextVisible);
    }

    base = nextBase;
    pending = nextPending;
    visible = nextVisible;

    notify();
    return true;
  }

  return {
    getState() {
      return visible;
    },

    apply(id, update) {
      if (pending.has(id)) {
        throw new Error("A pending change with this id already exists.");
      }

      const nextVisible = update(visible);

      pending.set(id, update);
      visible = nextVisible;
      notify();
    },

    confirm(id) {
      return settle(id, true);
    },

    rollback(id) {
      return settle(id, false);
    },

    subscribe(listener) {
      // Each subscription is independent, even for the same listener.
      const subscription = { listener };
      subscriptions.add(subscription);

      return function unsubscribe() {
        subscriptions.delete(subscription);
      };
    },
  };
}
